@Override
public ResolvedType visit(DoubleLiteralExpr node, Boolean solveLambdas) {
    if (node.getValue().toLowerCase().endsWith("f")) {
        return ResolvedPrimitiveType.FLOAT;
    }
    return ResolvedPrimitiveType.DOUBLE;
}

